import React, { useState, useRef, useEffect } from "react";
// import { DateRange } from "react-date-range";
// import { enUS } from "date-fns/locale"; // Import locale
// import "react-date-range/dist/styles.css";
// import "react-date-range/dist/theme/default.css";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import "react-date-range/dist/styles.css";
import "react-date-range/dist/theme/default.css";
import { FaCalendarAlt } from "react-icons/fa"; // Calendar icon
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../axiosService/ApiCall";
import { Spinner } from "react-bootstrap";
import Select from "react-select";
import { MdRefresh } from "react-icons/md";


function UserList() {
  const [userData, setUserData] = useState([]);
  const [pairName, setPairName] = useState("");
  const [type, setType] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [search, setSearch] = useState("");
  const [seller, setSeller] = useState("");
  // const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [loading, setLoading] = useState(false);
  const [limit, setLimit] = useState(10);
  const [showCalendar, setShowCalendar] = useState(false);
  const [totalItems, setTotalItems] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [is_Refreshing, setIs_Refreshing] = useState(false);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const calendarRef = useRef(null);

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  }


  // Close calendar when clicking outside
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const getTradehistory = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        pairName: pairName || "",
        type: type || "",
        buyerEmail: search || "",
        sellerEmail: seller || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
        status: status
      }).toString();
      // console.log('queryParams', queryParams)
      let params = {
        url: `user-TradeHistory?${queryParams}`,
        method: "GET",
      };
      const response = await makeApiRequest(params);
      // console.log('response', response)
      if (response.status) {

        setUserData(response.getTradeHistoryTblDetails);
        setLoading(false);
        setTotalPages(response.totalItems);
        // setTotalItems(response.pagination.totalItems)
      } else {
        setUserData([]);
        setLoading(false);
      }
    } catch (error) {
      console.log("error---", error);
      setLoading(false);
    }
  };

  // useEffect(() => {
  //   setLoading(true);

  //   getTradehistory(currentPage);
  // }, [pairName, search, seller, type, fromDate, toDate, currentPage, limit, status]);

  const handleClearFilters = async () => {
    setIsRefreshing(true); // Start spinning
    setSeller("");
    setType("");
    setIs_Refreshing(is_Refreshing ? false : true);
    setFromDate("");
    setToDate("");
    setShowCalendar("")
    setCurrentPage(1);

    setLimit(10);
    setStatus("");

    getTradehistory(1);

    const start = Date.now();

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      // ensure at least 500ms rotation
      await new Promise(resolve => setTimeout(resolve, 500 - elapsed));
    }


    setIsRefreshing(false); // Stop spinning
  };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };

  const columnsone = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Register Date",
      selector: (row) => dateFormat(row.dateTime) || "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Name",
      selector: (row) => row.buyerEmail || "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Email",
      selector: (row) => row.sellerEmail || "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Last Login",
      selector: (row) => dateFormat(row.dateTime) || "--",
      sortable: true,
      width: "250px",
    },

  ];

  const handleDateChange = (item) => {
    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
  };
  const handleSearch = (e) => {
    setSearch(e.target.value);
    handleReset()
  };

  const handleSellSearch = (e) => {
    setSeller(e.target.value);
    handleReset()
  };


  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };


  return (
    <div className="App">
      <div className="container-fluid " >
        <div className=" text-dark">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  User List
                </h3>
              </div>
              <div className="d-flex calendor-form align-items-end">
                <form className="d-flex gap-lg-2 align-items-end flex-wrap">
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Search by Name or Email
                    </label>
                    <input
                      type="text"
                      className="form-control search-bar"
                      id="exampleInputEmail1"
                      aria-describedby="emailHelp"
                      placeholder="Search by Name or Email"
                      value={search}
                      onChange={handleSearch}
                      style={{ width: "220px" }}
                    />
                  </div>

                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Register Date
                    </label>

                    <div
                      ref={calendarRef}
                      style={{ position: "relative", width: "250px" }}
                    >
                      <div
                        onClick={() => { setShowCalendar(!showCalendar); handleReset() }}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          padding: "6px",
                          border: "1px solid var(--color-1)",
                          borderRadius: "5px",
                          cursor: "pointer",
                          backgroundColor: "#fff",
                          fontSize: "14px",
                        }}
                      >
                        <span>
                          {fromDate && toDate
                            ? `${fromDate} - ${toDate}`
                            : "Select Date Range"}
                          {/* {range[0].startDate.toLocaleDateString()} - {range[0].endDate.toLocaleDateString()} */}
                        </span>
                        <FaCalendarAlt style={{ color: "#555" }} />
                      </div>

                      {/* Date range picker (shows when input is clicked) */}
                      {showCalendar && (
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: -80,
                            zIndex: 1000,
                            background: "#fff",
                            boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                            borderRadius: "5px",
                          }}
                        >
                          <DateRange
                            editableDateInputs={true}
                            onChange={handleDateChange}
                            moveRangeOnFirstSelection={false}
                            ranges={range}
                            locale={enUS}
                            rangeColors={["#58f9b0"]}
                          />
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Last Login
                    </label>

                    <div
                      ref={calendarRef}
                      style={{ position: "relative", width: "250px" }}
                    >
                      <div
                        onClick={() => { setShowCalendar(!showCalendar); handleReset() }}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          padding: "6px",
                          border: "1px solid var(--color-1)",
                          borderRadius: "5px",
                          cursor: "pointer",
                          backgroundColor: "#fff",
                          fontSize: "14px",
                        }}
                      >
                        <span>
                          {fromDate && toDate
                            ? `${fromDate} - ${toDate}`
                            : "Select Date Range"}
                          {/* {range[0].startDate.toLocaleDateString()} - {range[0].endDate.toLocaleDateString()} */}
                        </span>
                        <FaCalendarAlt style={{ color: "#555" }} />
                      </div>

                      {/* Date range picker (shows when input is clicked) */}
                      {showCalendar && (
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: -80,
                            zIndex: 1000,
                            background: "#fff",
                            boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                            borderRadius: "5px",
                          }}
                        >
                          <DateRange
                            editableDateInputs={true}
                            onChange={handleDateChange}
                            moveRangeOnFirstSelection={false}
                            ranges={range}
                            locale={enUS}
                            rangeColors={["#58f9b0"]}
                          />
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="mb-2">
                    <button
                      type="button"
                      className="form-label custom-nav-button-1 active cursor-pointer"
                      onClick={handleClearFilters}
                      disabled={isRefreshing}
                    >
                      <MdRefresh
                        style={{ fontSize: "24px" }}
                        className={isRefreshing ? "rotate-icon" : ""}
                      />
                    </button>
                  </div>
                </form>
              </div>

              <div className="liquidity-table-1">
                <DataTable
                  key={is_Refreshing}
                  columns={columnsone}
                  data={userData}
                  theme="solarized"
                  defaultSortAsc={true}
                  pagination
                  paginationServer
                  persistTableHead
                  paginationPerPage={limit}
                  paginationTotalRows={totalPages}
                  paginationRowsPerPageOptions={[5, 10, 15]}
                  paginationResetDefaultPage={resetPaginationToggle}
                  onChangeRowsPerPage={(newRowsPerPage) => {
                    setLimit(newRowsPerPage);
                    setCurrentPage(1);
                  }}
                  onChangePage={(page) => setCurrentPage(page)}
                  progressPending={loading}
                  progressComponent={
                    <div className="py-4 w-100" style={{ marginLeft: "45vw" }}>
                      <Spinner animation="border" />
                    </div>
                  }
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default UserList;
